public class ControlFlowDemo {
    public static void main(String[] args) {
        // Enhanced switch (Java 17+)
        int dayNumber = 3;
        String day = switch (dayNumber) {
            case 1 -> "Monday";
            case 2 -> "Tuesday";
            case 3 -> "Wednesday";
            default -> "Other Day";
        };
        System.out.println("Today is: " + day);

        // Enhanced for-each
        for (int i = 1; i <= 3; i++) {
            System.out.println("Step: " + i);
        }
    }
}

