public class StringDemo {
    public static void main(String[] args) {
        // String literal - stored in String Constant Pool
        String s1 = "CodeAlpha";
        String s2 = "CodeAlpha";
        System.out.println(s1 == s2); // true: refers to identical pooled object

        // Immutability demonstration
        s1.concat(" Internship");
        System.out.println(s1); // Still "CodeAlpha" because Strings cannot change in place

        // Proper reassignment
        s1 = s1.concat(" Internship");
        System.out.println(s1); // "CodeAlpha Internship"
    }
}

// High-level conceptual pseudo-code for AI Inference
public class ModelInference {
    public static double predict(double[] features, double[] weights, double bias) {
        double dotProduct = 0.0;
        for (int i = 0; i < features.length; i++) {
            dotProduct += features[i] * weights[i];
        }
        return 1.0 / (1.0 + Math.exp(-(dotProduct + bias))); // Sigmoid activation
    }
}

